      that.$func.myFunction('jlg-home', {
        functionName: 'goodsdata',
        data: {
          where: {
            is_best: true,
            is_on_sale: true
          },
          skip: skip,
          pageSize: that.pageSize
        }
      }).then(function (res) {
        var bestItems = res.result; // 获取新的数据
        if (that.currentPage === 1) {
          that.goodsList = bestItems; // 如果是第一页，清空原始数据列表
          that.oddgoodsList = that.goodsList.filter(function (item, index) {
            return index % 2 === 1;
          });
          that.evengoodsList = that.goodsList.filter(function (item, index) {
            return index % 2 === 0;
          });
        } else {
          that.goodsList = that.goodsList.concat(bestItems); // 否则追加数据到原始数据列表
          that.oddgoodsList = that.goodsList.filter(function (item, index) {
            return index % 2 === 1;
          });
          that.evengoodsList = that.goodsList.filter(function (item, index) {
            return index % 2 === 0;
          });
        }
        if (bestItems.length < that.pageSize) {
          that.loadingType = "noMore";
        } else {
          that.loadingType = "more";
        }
      }).catch(function (error) {
        console.error(error);
      });
